/* Initialize terminal */
static void init_terminal(void) {
    if (terminal_initialized) return;

    struct termios raw;
    tcgetattr(STDIN_FILENO, &orig_termios);
    terminal_initialized = 1;

    raw = orig_termios;
    raw.c_lflag &= ~(ECHO | ICANON);
    raw.c_cc[VMIN] = 0;
    raw.c_cc[VTIME] = 0;

    tcsetattr(STDIN_FILENO, TCSANOW, &raw);
}

/* Restore terminal */
static void restore_terminal(void) {
    if (!terminal_initialized) return;

    tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios);
    terminal_initialized = 0;
}

/* Get terminal size */
static void get_terminal_size(int *cols, int *rows) {
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0) {
        *cols = ws.ws_col;
        *rows = ws.ws_row;
    } else {
        *cols = 80;
        *rows = 24;
    }
}

/* Main loop */
static void main_loop(void) {
    int cols, rows;
    get_terminal_size(&cols, &rows);

    /* Set up terminal */
    init_terminal();

    /* Set up signal handlers */
    signal(SIGWINCH, sigwinch_handler);
    signal(SIGINT, sigint_handler);
    signal(SIGQUIT, sigquit_handler);

    /* Print message if provided */
    if (message) {
        printf("\033[2J\033[H");
        printf("\033[%d;%dH", rows/2, cols/2);
        printf("%s%s%s\n", "\033[1;37m", message, "\033[0m");
    }

    /* Main animation loop */
    while (1) {
        /* Clear screen */
        printf("\033[2J\033[H");

        /* Draw matrix */
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int char_idx = get_random_char();
                char c = normal_chars[char_idx];

                if (bold_chars && (rand() % 100 < 50)) {
                    printf("\033[1m%c\033[0m", c);
                } else {
                    printf("%c", c);
                }
            }
            printf("\n");
        }

        /* Handle keystrokes */
        handle_input();

        /* Sleep for update delay */
        usleep(update_delay * 1000);
    }
}

/* Handle input */
static void handle_input(void) {
    fd_set readfds;
    FD_ZERO(&readfds);
    FD_SET(STDIN_FILENO, &readfds);

    struct timeval tv;
    tv.tv_sec = 0;
    tv.tv_usec = update_delay * 1000;

    if (select(STDIN_FILENO + 1, &readfds, NULL, NULL, &tv) > 0) {
        char buf[10];
        ssize_t n = read(STDIN_FILENO, buf, sizeof(buf) - 1);
        if (n > 0) {
            buf[n] = '\0';

            /* Handle keystrokes */
            if (screensaver_mode) {
                exit(0);
            }

            for (int i = 0; buf[i]; i++) {
                char c = buf[i];

                if (c == 'q' || c == 'Q') {
                    exit(0);
                } else if (c == 'a' || c == 'A') {
                    async_scroll = !async_scroll;
                } else if (c == 'b' || c == 'B') {
                    bold_chars = 1;
                } else if (c == 'n') {
                    bold_chars = 0;
                    all_bold = 0;
                } else if (c >= '0' && c <= '9') {
                    update_delay = c - '0';
                } else if (c == '!') {
                    color = "red";
                } else if (c == '@') {
                    color = "green";
                } else if (c == '#') {
                    color = "yellow";
                } else if (c == '$') {
                    color = "blue";
                } else if (c == '%') {
                    color = "magenta";
                } else if (c == '^') {
                    color = "cyan";
                } else if (c == '&') {
                    color = "white";
                } else if (c == ')') {
                    color = "black";
                }
            }
        }
    }
}

